/* AMPM emergency POS. All prices and totals are stored as integer cents. */
'use strict';
const $=id=>document.getElementById(id), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const seed=JSON.parse($('seed-data').textContent), PRACTICE=new URLSearchParams(location.search).has('practica'),KEY='ampm.emergency.v2'+(PRACTICE?'.practica':''),money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n/100), date=v=>new Date(v).toLocaleString('es-SV',{timeZone:'America/El_Salvador',dateStyle:'medium',timeStyle:'short'}),uid=()=>crypto.randomUUID();
const icons={cart:'M3 3h2l2 12h12l2-9H6 M9 20h.01 M18 20h.01',history:'M3 11a9 9 0 1 1 3 8 M3 4v7h7 M12 7v5l3 2',box:'M3 6l9-4 9 4v12l-9 4-9-4Z M3 6l9 4 9-4 M12 10v12 M7 4l10 4',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 2h6l1 3 3 1 3 4-2 2 1 4-4 4-3-1-3 2-4-2-1-4-3-2 1-5 3-1Z',shield:'M12 2l9 4v6c0 5-5 8-9 10-4-2-9-5-9-10V6Z M8 12l3 3 5-6',store:'M3 10v11h18V10 M2 10l2-7h16l2 7 M2 10q3 4 5 0 3 4 5 0 3 4 5 0 3 4 5 0 M9 21v-7h6v7',bolt:'M13 2L4 14h7l-1 8 10-13h-7Z',search:'M20 20l-5-5 M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14',scan:'M3 7V3h4 M17 3h4v4 M21 17v4h-4 M7 21H3v-4 M7 8v8 M10 8v8 M14 8v8 M17 8v8',receipt:'M5 2l3 2 4-2 4 2 3-2v20l-3-2-4 2-4-2-3 2Z M8 8h8 M8 12h8 M8 16h4',database:'M3 5c0-4 18-4 18 0s-18 4-18 0v14c0 4 18 4 18 0V5 M3 12c0 4 18 4 18 0',check:'M5 12l4 4L20 5',trash:'M3 6h18 M9 6V3h6v3 M5 6l1 15h12l1-15 M10 10v7 M14 10v7',download:'M12 3v12l-4-4 M12 15l4-4 M4 16v5h16v-5',sync:'M3 11a9 9 0 0 1 16-6l2 3 M21 3v5h-5 M21 13a9 9 0 0 1-16 6l-2-3 M3 21v-5h5'};
const icon=k=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[k]||icons.box}"/></svg>`;
function fillIcons(){document.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon));}
let recoveryRaw=null,db,view='sale',catalogPage=0,historyPage=0,lastSaleId=null,importData=null,toastTimer,storageFailed=false,syncing=false;
const emptyDraft=()=>({items:[],received:'',reference:'',method:'Efectivo',channel:'Tienda',delivery:{orderId:'',rider:'',notes:''}});
function initial(){return {version:2,practice:PRACTICE,revision:0,device:uid(),seq:1,profile:{store:'',till:'',cashier:''},catalog:structuredClone(seed),sessions:[],active:null,sales:[],draft:emptyDraft(),audit:[],lastBackup:null};}
function load(){const raw=localStorage.getItem(KEY);if(!raw){const d=initial();localStorage.setItem(KEY,JSON.stringify(d));return d;}const d=JSON.parse(raw);if(d.version!==2||!Array.isArray(d.sales)||!Array.isArray(d.catalog?.products))throw Error('El registro local no tiene un formato válido. Recupera un respaldo antes de continuar.');d.draft.channel??='Tienda';d.draft.delivery??={orderId:'',rider:'',notes:''};return d;}
function storageError(e){storageFailed=true;$('storage-alert').classList.remove('hidden');$('storage-alert').textContent='No se pudo guardar en este navegador. No cierres esta ventana. Descarga un respaldo desde Registro de ventas. '+e.message;}
try{db=load();}catch(e){try{recoveryRaw=localStorage.getItem(KEY);}catch{}db=initial();storageError(e);}
async function transaction(fn,paint=true){
  const work=()=>{if(storageFailed)throw Error('El almacenamiento no está disponible. Descarga un respaldo.');const current=load(),next=structuredClone(current);fn(next);next.revision=current.revision+1;try{localStorage.setItem(KEY,JSON.stringify(next));}catch(e){storageError(e);throw Error('No se guardó el cambio. El registro anterior sigue intacto.');}db=next;if(paint)render();return next;};
  try{return navigator.locks?await navigator.locks.request(KEY,work):work();}catch(e){toast(e.message);throw e;}
}
function toast(msg){clearTimeout(toastTimer);$('toast').textContent=msg;$('toast').classList.add('show');toastTimer=setTimeout(()=>$('toast').classList.remove('show'),6500);}
const active=d=>d.sessions.find(s=>s.id===d.active),sum=items=>Core.total(items), quantity=items=>items.reduce((n,p)=>n+p.qty,0),pending=d=>d.sales.filter(v=>!v.void&&!v.posReference);
function navigate(to){view=to;document.querySelectorAll('.view').forEach(e=>e.classList.toggle('hidden',e.id!=='view-'+to));document.querySelectorAll('[data-view]').forEach(e=>e.classList.toggle('active',e.dataset.view===to));render();}
function render(){
  $('network').textContent=PRACTICE?'MODO PRÁCTICA':navigator.onLine?'Red disponible':'Sin conexión';$('network').className='badge '+(PRACTICE||!navigator.onLine?'amber':'');$('pending-count').textContent=pending(db).length;
  const s=active(db);$('op-title').textContent=s?`${s.store} · Caja ${s.till} · ${s.cashier}`:'Prepara tu caja antes de comenzar';$('op-sub').textContent=s?`${s.reason} · Inicio: ${date(s.opened)} · Ventas guardadas en este equipo`:'Selecciona la tienda, la caja y el responsable de esta emergencia.';$('op-status').textContent=s?'Emergencia activa':'Sin jornada activa';$('session-label').textContent=s?'Ver jornada':'Preparar caja';
  $('catalog-short').textContent=db.catalog.products.length.toLocaleString('es-SV')+' productos';$('source-title').textContent=db.catalog.source;$('source-date').textContent=(db.catalog.syncedAt?'Descargado: '+date(db.catalog.syncedAt):'Fecha de precios sin verificar')+' · PriceC / USD';
  if(db.catalog.syncedAt&&Date.now()-Date.parse(db.catalog.syncedAt)>86400000)$('source-date').textContent+=' · Más de 24 h: revisa precios';
  renderCart();if(view==='catalog')renderCatalog();if(view==='history')renderHistory();if(view==='setup')renderSetup();if(view==='help')renderHelp();fillIcons();
}
function renderCart(){
  const items=db.draft.items,channel=db.draft.channel,delivery=Core.isDelivery(channel),q=Core.quote(items,channel);
  $('channel').value=channel;$('delivery-fields').classList.toggle('hidden',!delivery);
  for(const [id,key] of [['order-id','orderId'],['rider-name','rider'],['delivery-notes','notes']])$(id).value=db.draft.delivery[key];
  $('delivery-summary').textContent=delivery?'PriceC + 10% · IVA 13% incluido · Redondeo por unidad a 2 decimales.':'Precio de tienda · PriceC en USD';
  $('cart-body').innerHTML=items.map((p,i)=>{const unit=Core.unitPrice(p.cents,channel);return `<tr><td><b>${esc(p.name)}</b><small>${esc(p.code)}</small></td><td>${money(unit)}${delivery?'<small>PriceC '+money(p.cents)+'</small>':''}</td><td><div class="quantity"><button data-qty="${i}" data-delta="-1" aria-label="Reducir ${esc(p.name)}">−</button><span>${p.qty}</span><button data-qty="${i}" data-delta="1" aria-label="Aumentar ${esc(p.name)}">+</button></div></td><td class="right"><b>${money(unit*p.qty)}</b></td><td><button class="remove" data-remove="${i}" aria-label="Quitar ${esc(p.name)}">${icon('trash')}</button></td></tr>`;}).join('');
  $('cart-empty').classList.toggle('hidden',items.length>0);$('line-count').textContent=items.length;$('item-count').textContent=quantity(items)+' unidades';$('sale-total').textContent=money(q.total);$('total-units').textContent=quantity(items)+' unidades · '+channel;
  $('price-breakdown').classList.toggle('hidden',!delivery);$('price-breakdown').innerHTML=delivery?pricingDetails(q):'';
  $('platform-option').disabled=!delivery;$('platform-option').hidden=!delivery;$('method').value=db.draft.method;$('received').value=db.draft.received;$('reference').value=db.draft.reference;paymentView();$('clear-cart').disabled=!items.length;$('checkout').disabled=!items.length||storageFailed;
  $('last-sale').classList.toggle('hidden',!lastSaleId);if(lastSaleId)$('last-sale').innerHTML=`<button class="text-button" id="last-print">${icon('receipt')} Ver última venta</button>`;
}
function pricingDetails(p){return `<div class="price-row"><span>Subtotal PriceC</span><b>${money(p.baseTotal)}</b></div><div class="price-row"><span>Incremento delivery 10%</span><b>${money(p.surcharge)}</b></div><div class="price-row tax-row"><span>Base sin IVA</span><b>${money(p.net)}</b></div><div class="price-row"><span>IVA 13% incluido</span><b>${money(p.vat)}</b></div><p class="hint">El IVA ya está incluido en el total.</p>`;}
function deliveryDetails(v){return v.channel&&Core.isDelivery(v.channel)?`<div class="delivery-review"><b>${esc(v.channel)} · Orden ${esc(v.delivery.orderId)}</b><p>Rider: ${esc(v.delivery.rider||'Por completar a mano')}</p>${v.delivery.notes?'<p>'+esc(v.delivery.notes)+'</p>':''}</div>`:'';}
function paymentView(){const method=$('method').value,cash=method==='Efectivo',platform=method==='Plataforma delivery',n=Core.cents($('received').value),total=Core.quote(db.draft.items,db.draft.channel).total;$('cash-fields').classList.toggle('hidden',!cash);$('card-fields').classList.toggle('hidden',method!=='Tarjeta BAC');$('platform-fields').classList.toggle('hidden',!platform);$('change-label').textContent=platform?'Efectivo que ingresa en caja':cash&&n!==null&&n<total?'Falta por recibir':'Cambio a entregar';$('change').textContent=money(!cash||n===null?0:Math.abs(n-total));$('change').style.color=cash&&n!==null&&n<total?'#b73a25':'';}
function search(){const q=$('search').value.trim(),normalized=Core.norm(q);if(!normalized){$('search-results').innerHTML='';return;}const matches=db.catalog.products.filter(p=>Core.norm(p.code).includes(normalized)||Core.norm(p.name).includes(normalized));matches.sort((a,b)=>(b.code.toLowerCase()===q.toLowerCase())-(a.code.toLowerCase()===q.toLowerCase()));$('search-results').innerHTML=matches.length?`<div class="result-list">${matches.slice(0,8).map(p=>`<button class="result" data-product="${esc(p.code)}" ${p.cents<=0?'disabled':''}><span class="result-main"><b>${esc(p.name)}</b><small>${esc(p.code)}${p.category?' · '+esc(p.category):''}</small></span><span class="result-price">${p.cents>0?money(Core.unitPrice(p.cents,db.draft.channel)):'Sin precio'}</span><span class="result-plus">+</span></button>`).join('')}</div>${matches.length>8?'<p class="hint spacer">'+matches.length+' coincidencias. Afina la búsqueda para ver el producto.</p>':''}`:'<p class="hint spacer">No encontramos ese producto. Revisa el código o actualiza el catálogo.</p>';}
async function add(code){const q=Number($('add-qty').value);if(!Number.isInteger(q)||q<1||q>9999)return toast('Usa una cantidad entera entre 1 y 9,999.');await transaction(d=>{const p=d.catalog.products.find(p=>p.code===code);if(!p||p.cents<=0)throw Error('Producto sin un precio válido.');const exists=d.draft.items.find(x=>x.code===code);if(exists){if(exists.qty+q>9999)throw Error('Cantidad máxima: 9,999.');exists.qty+=q;}else d.draft.items.push({...p,qty:q});});$('search').value='';$('add-qty').value=1;search();$('search').focus();}
function modal(title,body,actions){$('modal-title').textContent=title;$('modal-body').innerHTML=body;$('modal-error').textContent='';$('modal-actions').innerHTML='';for(const a of actions){const b=document.createElement('button');b.textContent=a.label;b.className='button '+(a.style||'secondary');b.onclick=async()=>{b.disabled=true;try{await a.run();}catch(e){$('modal-error').textContent=e.message;}finally{b.disabled=false;}};$('modal-actions').append(b);}if(!$('modal').open)$('modal').showModal();fillIcons();}
function closeModal(){$('modal').close();}
function openSession(){const s=active(db);if(s){navigate('setup');return;}modal('Preparar caja de emergencia',`<p class="hint">Identifica esta jornada. El catálogo está configurado en PriceC / USD.</p><div class="form-grid spacer"><div><label for="s-store">Tienda</label><select id="s-store"><option value="">Selecciona una tienda</option>${['AMPM01','AMPM02','AMPM03'].map(t=>`<option ${db.profile.store===t?'selected':''}>${t}</option>`).join('')}</select></div><div><label for="s-till">Número de caja</label><input id="s-till" maxlength="12" placeholder="Ej. 01" value="${esc(db.profile.till)}"></div><div><label for="s-cashier">Responsable</label><input id="s-cashier" maxlength="80" placeholder="Nombre del cajero" value="${esc(db.profile.cashier)}"></div><div><label for="s-reason">Motivo</label><select id="s-reason"><option>Corte de energía</option><option>Falla del sistema de caja</option><option>Sin conexión</option><option>Otra contingencia</option></select></div><div><label for="s-float">Fondo inicial en efectivo (USD)</label><input id="s-float" inputmode="decimal" value="0.00"></div></div><label class="check-label spacer"><input id="s-verified" type="checkbox">Verifiqué que este catálogo y sus precios corresponden a la tienda seleccionada.</label>`,[{label:'Cancelar',run:closeModal},{label:'Iniciar jornada',style:'primary',run:async()=>{const store=$('s-store').value,till=$('s-till').value.trim(),cashier=$('s-cashier').value.trim(),reason=$('s-reason').value,opening=Core.cents($('s-float').value);if(!store||!till||!cashier||opening===null)throw Error('Completa tienda, caja, responsable y fondo inicial.');if(!/^[A-Za-z0-9_-]+$/.test(till))throw Error('La caja debe usar letras, números o guiones.');if(!$('s-verified').checked)throw Error('Verifica el catálogo de la tienda antes de iniciar.');await transaction(d=>{if(d.active)throw Error('Ya existe una jornada activa.');if(d.catalog.store&&d.catalog.store!==store)throw Error('El catálogo está filtrado para otra tienda.');const s={id:uid(),store,till,cashier,reason,opening,opened:new Date().toISOString(),closed:null};d.sessions.push(s);d.active=s.id;d.profile={store,till,cashier};});closeModal();navigate('sale');$('search').focus();toast('Jornada iniciada. Ya puedes registrar ventas.');}}]);}
function reviewCheckout(){
  if(!active(db)){openSession();return;}
  const channel=$('channel').value,method=$('method').value,reference=$('reference').value.trim(),received=Core.cents($('received').value);
  let pay,delivery,pricing;
  try{delivery=Core.deliveryData(channel,{orderId:$('order-id').value,rider:$('rider-name').value,notes:$('delivery-notes').value});pricing=Core.quote(db.draft.items,channel);pay=Core.payment(db.draft.items,method,received,reference,channel);Core.assertUniqueOrder(db.sales,active(db).store,channel,delivery);}catch(e){toast(e.message);return;}
  const frozen=JSON.stringify(db.draft),sessionId=db.active;
  modal('Revisar y registrar venta',`<div class="receipt-preview"><p>${esc(active(db).store)} · Caja ${esc(active(db).till)} · ${esc(active(db).cashier)}</p>${deliveryDetails({channel,delivery})}<div class="checkline"><span>Unidades</span><b>${quantity(db.draft.items)}</b></div><div class="checkline"><span>Método</span><b>${esc(method)}</b></div>${delivery?pricingDetails(pricing):''}<div class="checkline"><span>${method==='Plataforma delivery'?'Efectivo en caja':'Recibido'}</span><b>${money(pay.received)}</b></div><div class="checkline"><span>Cambio</span><b>${money(pay.change)}</b></div><div class="receipt-total"><span>Total</span><span>${money(pay.total)}</span></div></div><p class="hint spacer">${method==='Plataforma delivery'?'Confirma que la plataforma gestiona este cobro. Este registro no procesa pagos ni confirma liquidaciones.':'Confirma después de recibir el pago.'} ${delivery?'Verifica la orden y los productos; después imprime el ticket para la firma del rider.':'Se guardará un comprobante de contingencia con folio único.'}</p>`,[{label:'Volver',run:closeModal},{label:'Confirmar venta',style:'primary',run:async()=>{
    let id;await transaction(d=>{if(d.active!==sessionId||JSON.stringify(d.draft)!==frozen)throw Error('La jornada o la venta cambió. Revisa la venta de nuevo.');const s=active(d);Core.assertUniqueOrder(d.sales,s.store,channel,delivery);id=uid();const folio=`${PRACTICE?'PRACTICA':'EM'}-${s.store}-${s.till}-${s.opened.slice(0,10).replaceAll('-','')}-${d.device.slice(0,6).toUpperCase()}-${String(d.seq).padStart(5,'0')}`;d.seq++;d.sales.push({id,folio,sessionId:s.id,store:s.store,till:s.till,cashier:s.cashier,created:new Date().toISOString(),items:structuredClone(d.draft.items),...pay,method,reference,channel,delivery,pricing,currency:'USD',source:d.catalog.source,priceDate:d.catalog.syncedAt,void:null,posReference:null});d.draft=emptyDraft();});
    lastSaleId=id;render();modal('Venta registrada',`<div class="success-circle">${icon('check')}</div><h3 class="center">${esc(db.sales.find(v=>v.id===id).folio)}</h3><p class="hint center spacer">${delivery?'Imprime el ticket, solicita la firma del rider y conserva la copia en la sucursal.':'Cambio a entregar: '+money(pay.change)}<br>Guardada en este navegador.</p>`,[{label:delivery?'Ticket para firma del rider':'Ver e imprimir comprobante',run:()=>printSale(id)},{label:'Nueva venta',style:'primary',run:()=>{closeModal();$('search').focus();}}]);
  }}]);
}
function printSale(id){
  const v=db.sales.find(v=>v.id===id);if(!v)return;
  const ticket=Receipt.html(v,document.querySelector('.brand img').src,{practice:PRACTICE,signature:true});
  modal(Core.isDelivery(v.channel||'Tienda')?'Ticket para firma del rider · 80 mm':'Comprobante · 80 mm',`<p class="hint">Selecciona la impresora térmica de esta sucursal: papel 80 mm, escala 100%, sin encabezados ni pies de página. La impresión abre el diálogo del navegador.</p><div class="ticket-preview-wrap">${ticket}</div>`,[{label:'Volver al detalle',run:()=>saleDetail(id)},{label:'Imprimir en térmica',style:'primary',run:()=>{$('print-area').innerHTML=ticket;window.print();}}]);
}
function printerHelp(){modal('Preparar impresora térmica · 80 mm',`<ol class="printer-steps"><li>En Windows, verifica que la impresora de facturas esté instalada y pueda imprimir una página de prueba.</li><li>Al imprimir un ticket AMPM, selecciona esa impresora. Usa papel de <b>80 mm</b> o rollo de recibos en sus preferencias.</li><li>Usa <b>escala 100%</b>, sin encabezados ni pies de página. El ticket ocupa 72 mm de ancho útil.</li><li>Imprime una prueba y verifica los extremos, los importes y la firma. Si se corta, revisa el tamaño de papel y el área imprimible del controlador.</li></ol><p class="hint">Cada computadora recuerda su selección en el navegador. AMPM abre el diálogo de impresión; no envía automáticamente a una impresora ni modifica el sistema de facturación.</p>`,[{label:'Cerrar',run:closeModal},{label:'Ver ticket de prueba',style:'primary',run:printerTest}]);}
function printerTest(){
  const s=active(db)||db.profile,items=[{code:'PRUEBA-001',name:'Producto de prueba de impresión',category:'',cents:1000,qty:1}],channel='PedidosYa',pricing=Core.quote(items,channel);
  const ticket=Receipt.html({folio:'PRUEBA · NO ES UNA VENTA',created:new Date().toISOString(),store:s.store||'Sucursal de prueba',till:s.till||'01',cashier:s.cashier||'Prueba',channel,delivery:{orderId:'PRUEBA-80MM',rider:'',notes:'Verificar que el texto no se corte.'},items,pricing,total:pricing.total,method:'Plataforma delivery',received:0,change:0},document.querySelector('.brand img').src,{practice:true,signature:true});
  modal('Prueba de impresión · no registra venta',`<div class="ticket-preview-wrap">${ticket}</div>`,[{label:'Volver',run:printerHelp},{label:'Imprimir prueba',style:'primary',run:()=>{$('print-area').innerHTML=ticket;window.print();}}]);
}
function heading(k,title,sub){return `<div class="page-heading"><div><div class="eyebrow">${k}</div><h1>${title}</h1><p class="subtitle">${sub}</p></div></div>`;}
function renderCatalog(){const c=db.catalog;const q=$('cat-search')?.value||'',filter=$('cat-filter')?.value||'all';$('view-catalog').innerHTML=heading('PRECIOS DISPONIBLES','Catálogo y precios','Actualiza con Internet. Sigue vendiendo con la última copia guardada.')+`<div class="actions"><button class="button primary" id="sync" ${syncing?'disabled':''}>${icon('sync')}${syncing?'Consultando MSTG…':'Actualizar desde MSTG'}</button><button class="button secondary" id="upload">Importar Excel o CSV</button><button class="button secondary" id="export-catalog">Descargar catálogo CSV</button></div><div class="stats"><div class="stat"><span>Productos en el catálogo</span><strong>${c.products.length.toLocaleString('es-SV')}</strong></div><div class="stat"><span>Con precio para vender</span><strong>${c.products.filter(p=>p.cents>0).length.toLocaleString('es-SV')}</strong></div><div class="stat"><span>Sin precio · cobro bloqueado</span><strong>${c.products.filter(p=>p.cents<=0).length}</strong></div></div><div class="panel content-panel"><h2>${esc(c.source)}</h2><p class="hint">${c.syncedAt?'Descarga verificada: '+date(c.syncedAt):'Vigencia no verificada'} · PriceC · USD${c.store?' · Tienda '+esc(c.store):' · Catálogo del informe SAL'}</p><p class="hint">La hora indica cuándo se descargó el informe; la vigencia comercial depende de MSTG.</p><div class="path spacer">AMPM SAL → Mis informes → Informes MSTG - Salv → <b>Precios Productos</b></div>${location.protocol==='file:'?'<div class="alert">Para sincronizar, abre <b>Iniciar AMPM.vbs</b>. Este HTML funciona sin conexión con el catálogo guardado. Los registros de esta apertura directa son independientes de los del acceso local: usa un respaldo para trasladarlos.</div>':''}<div class="filterbar spacer"><input id="cat-search" placeholder="Buscar código, nombre o categoría" aria-label="Buscar catálogo" value="${esc(q)}"><select id="cat-filter" aria-label="Filtrar precios"><option value="all">Todos los productos</option><option value="zero" ${filter==='zero'?'selected':''}>Sin precio</option></select></div><div id="catalog-table"></div></div>`;paintCatalog();$('cat-search').oninput=()=>{catalogPage=0;paintCatalog();};$('cat-filter').onchange=()=>{catalogPage=0;paintCatalog();};$('sync').onclick=syncCatalog;$('upload').onclick=()=>$('import-file').click();$('export-catalog').onclick=()=>download('catalogo-ampm.csv',Core.exportCSV(['ItemLoockupCode','Item Description','Category','PriceC'],c.products.map(p=>[p.code,p.name,p.category,(p.cents/100).toFixed(2)])),'text/csv;charset=utf-8');}
function paintCatalog(){const q=Core.norm($('cat-search').value),zero=$('cat-filter').value==='zero',products=db.catalog.products.filter(p=>(!zero||p.cents<=0)&&(!q||Core.norm(p.code+p.name+p.category).includes(q)));catalogPage=Math.min(catalogPage,Math.max(0,Math.ceil(products.length/30)-1));$('catalog-table').innerHTML=`<div class="table-wrap"><table class="data-table"><thead><tr><th>CÓDIGO</th><th>PRODUCTO</th><th>CATEGORÍA</th><th class="right">PRICEC / USD</th></tr></thead><tbody>${products.slice(catalogPage*30,catalogPage*30+30).map(p=>`<tr><td class="mono">${esc(p.code)}</td><td>${esc(p.name)}</td><td>${esc(p.category||'—')}</td><td class="right">${p.cents>0?money(p.cents):'<span class="warning-price">Sin precio</span>'}</td></tr>`).join('')||'<tr><td colspan="4">No hay coincidencias.</td></tr>'}</tbody></table></div><div class="pager"><span>${products.length} productos · Página ${catalogPage+1} de ${Math.max(1,Math.ceil(products.length/30))}</span><button class="button" id="cat-prev" ${catalogPage===0?'disabled':''}>←</button><button class="button" id="cat-next" ${(catalogPage+1)*30>=products.length?'disabled':''}>→</button></div>`;$('cat-prev').onclick=()=>{catalogPage--;paintCatalog();};$('cat-next').onclick=()=>{catalogPage++;paintCatalog();};}
async function syncCatalog(){if(location.protocol==='file:')return toast('Abre Iniciar AMPM.vbs para actualizar desde MicroStrategy.');if(db.draft.items.length)return toast('Termina o vacía el carrito antes de actualizar precios.');if(syncing)return;syncing=true;renderCatalog();try{const r=await fetch('/api/catalog',{method:'POST',headers:{'Content-Type':'application/json','X-AMPM-Request':'catalog'},body:'{}',signal:AbortSignal.timeout(180000)});const body=await r.json();if(!r.ok)throw Error(body.error||'No se pudo actualizar MSTG.');prepareImport([{name:'MicroStrategy',rows:[body.headers,...body.rows]}],{source:'MicroStrategy · Precios Productos',syncedAt:body.downloadedAt,reportId:body.reportId});}catch(e){toast(e.name==='TimeoutError'?'La consulta agotó el tiempo. Conservamos el catálogo anterior.':e.message);}finally{syncing=false;renderCatalog();}}
function prepareImport(sheets,meta){importData={sheets,meta};const options=sheets.map((s,i)=>`<option value="${i}">${esc(s.name)}</option>`).join('');modal('Revisar catálogo antes de aplicar',`<p class="hint">${esc(meta.source)}. Confirma las columnas; el precio de cobro es PriceC en USD.</p><label class="field-label" for="import-sheet">Hoja</label><select id="import-sheet">${options}</select><div id="mapping-fields" class="form-grid spacer"></div><div id="import-preview"></div>`,[{label:'Cancelar',run:closeModal},{label:'Aplicar catálogo',style:'primary',run:async()=>{const result=readImport();await transaction(d=>{if(d.draft.items.length)throw Error('Termina o vacía el carrito antes de cambiar precios.');if(d.active&&result.store&&active(d).store!==result.store)throw Error('La tienda del catálogo no coincide con la jornada activa.');d.catalog={...meta,products:result.products,store:result.store};d.audit.push({at:new Date().toISOString(),action:'catalog',source:meta.source,count:result.products.length});});closeModal();toast('Catálogo actualizado: '+result.products.length+' productos. Disponible sin conexión.');}}]);$('import-sheet').onchange=buildMapping;buildMapping();}
function buildMapping(){const rows=importData.sheets[Number($('import-sheet').value)].rows;let hi=rows.findIndex(r=>{const m=Core.mapping(r);return m.code>=0&&m.name>=0;});if(hi<0)hi=0;importData.rows=rows.slice(hi+1);importData.headers=rows[hi]||[];const map=Core.mapping(importData.headers);$('mapping-fields').innerHTML=Object.entries({code:'Código',name:'Descripción',price:'Precio de venta (PriceC)',category:'Categoría',store:'Tienda'}).map(([k,label])=>`<div><label for="map-${k}">${label}</label><select id="map-${k}"><option value="-1">${['category','store'].includes(k)?'No disponible':'Selecciona columna'}</option>${importData.headers.map((h,i)=>`<option value="${i}" ${map[k]===i?'selected':''}>${esc(h)}</option>`).join('')}</select></div>`).join('')+'<div><label for="import-store">Filtrar tienda</label><select id="import-store"><option value="">Todas / catálogo general</option></select></div>';
  for(const k of Object.keys(map))$('map-'+k).onchange=()=>{if(k==='store')updateStores();previewImport();};updateStores();$('import-store').onchange=previewImport;previewImport();}
function updateStores(){const index=Number($('map-store').value),stores=index<0?[]:[...new Set(importData.rows.map(r=>String(r[index]??'').trim()).filter(Boolean))];$('import-store').innerHTML='<option value="">Todas / catálogo general</option>'+stores.map(s=>`<option>${esc(s)}</option>`).join('');if(stores.includes(db.profile.store))$('import-store').value=db.profile.store;}
function readImport(){const map=Object.fromEntries(['code','name','price','category','store'].map(k=>[k,Number($('map-'+k).value)]));if(Core.norm(importData.headers[map.price])!=='pricec')throw Error('Selecciona PriceC (o Price C). No se utilizará Price (PROM) para cobrar.');return Core.catalog(importData.headers,importData.rows,map,$('import-store').value);}
function previewImport(){try{const p=readImport();$('import-preview').innerHTML=`<div class="alert">${p.products.length} productos · ${p.zero} sin precio (se bloquearán) · ${p.repeated} duplicados idénticos unificados.</div><table class="data-table"><thead><tr><th>PRODUCTO</th><th>PRICEC</th></tr></thead><tbody>${p.products.slice(0,4).map(p=>`<tr><td>${esc(p.name)}<small>${esc(p.code)}</small></td><td>${money(p.cents)}</td></tr>`).join('')}</tbody></table>`;}catch(e){$('import-preview').innerHTML='<div class="alert error">'+esc(e.message)+'</div>';}}
function renderHistory(){const q=$('history-search')?.value||'',filter=$('history-filter')?.value||'pending';const sales=db.sales.filter(v=>!v.void);$('view-history').innerHTML=heading('CONTROL Y RECUPERACIÓN','Registro de ventas','Consulta comprobantes, respalda la jornada y registra su traslado al sistema de caja.')+`<div class="actions"><button class="button primary" id="export-sales">${icon('download')} Exportar ventas CSV</button><button class="button secondary" id="backup">Crear respaldo</button><button class="button secondary" id="restore">Restaurar respaldo</button></div><div class="stats"><div class="stat"><span>Ventas válidas · todas las jornadas</span><strong>${sales.length}</strong></div><div class="stat"><span>Total vendido · todas las jornadas</span><strong>${money(sales.reduce((n,v)=>n+v.total,0))}</strong></div><div class="stat"><span>Pendientes de registrar en caja</span><strong>${pending(db).length}</strong></div></div><p class="hint">Último respaldo generado: ${db.lastBackup?date(db.lastBackup):'Aún no has creado uno'}. Guarda el archivo fuera de este navegador.</p><div class="panel content-panel"><div class="filterbar"><input id="history-search" value="${esc(q)}" placeholder="Buscar folio, orden, plataforma o tienda" aria-label="Buscar ventas"><select id="history-filter" aria-label="Estado de ventas"><option value="pending">Pendientes de registrar</option><option value="all" ${filter==='all'?'selected':''}>Todas las ventas</option><option value="registered" ${filter==='registered'?'selected':''}>Registradas en caja</option><option value="void" ${filter==='void'?'selected':''}>Anuladas</option></select></div><div id="history-table"></div></div>`;paintHistory();$('history-search').oninput=()=>{historyPage=0;paintHistory();};$('history-filter').onchange=()=>{historyPage=0;paintHistory();};$('export-sales').onclick=exportSales;$('backup').onclick=backup;$('restore').onclick=()=>$('restore-file').click();}
function paintHistory(){const q=Core.norm($('history-search').value),filter=$('history-filter').value,list=[...db.sales].reverse().filter(v=>(!q||Core.norm(v.folio+v.store+v.cashier+(v.channel||'Tienda')+(v.delivery?.orderId||'')).includes(q))&&(filter==='all'||filter==='pending'&&!v.void&&!v.posReference||filter==='registered'&&!v.void&&v.posReference||filter==='void'&&v.void));historyPage=Math.min(historyPage,Math.max(0,Math.ceil(list.length/25)-1));$('history-table').innerHTML=`<div class="table-wrap"><table class="data-table"><thead><tr><th>COMPROBANTE</th><th>TIENDA / CAJERO</th><th>TOTAL</th><th>ESTADO</th><th></th></tr></thead><tbody>${list.slice(historyPage*25,historyPage*25+25).map(v=>`<tr><td>${esc(v.folio)}<small>${date(v.created)}</small>${v.delivery?'<small>'+esc(v.channel)+' · Orden '+esc(v.delivery.orderId)+'</small>':''}</td><td>${esc(v.store)} · ${esc(v.till)}<small>${esc(v.cashier)}</small></td><td>${money(v.total)}<small>${esc(v.method)}</small></td><td><span class="badge ${v.void?'neutral':v.posReference?'':'amber'}">${v.void?'Anulada':v.posReference?'Registrada en caja':'Pendiente'}</span></td><td><button class="text-button" data-sale="${esc(v.id)}">Ver detalle →</button></td></tr>`).join('')||'<tr><td colspan="5"><div class="empty"><h3>No hay ventas en esta selección</h3><p>Las ventas que registres aparecerán aquí.</p></div></td></tr>'}</tbody></table></div><div class="pager"><span>${list.length} ventas · Página ${historyPage+1}</span><button id="hist-prev" class="button" ${historyPage===0?'disabled':''}>←</button><button id="hist-next" class="button" ${(historyPage+1)*25>=list.length?'disabled':''}>→</button></div>`;$('hist-prev').onclick=()=>{historyPage--;paintHistory();};$('hist-next').onclick=()=>{historyPage++;paintHistory();};}
function saleDetail(id){const v=db.sales.find(v=>v.id===id);if(!v)return;const actions=[{label:v.delivery?'Ticket para firma del rider':'Ver e imprimir',run:()=>printSale(id)}];if(!v.void&&!v.posReference){actions.push({label:'Anular',style:'danger',run:()=>voidSale(id)},{label:'Registrar traslado a caja',style:'primary',run:()=>reconcile(id)});}modal('Detalle del comprobante',`<p class="mono">${esc(v.folio)}</p><p class="hint spacer">${date(v.created)} · ${esc(v.store)} · Caja ${esc(v.till)}<br>${esc(v.cashier)} · ${esc(v.method)}</p>${deliveryDetails(v)}<div class="table-wrap"><table class="data-table spacer"><thead><tr><th>PRODUCTO</th><th>CANT.</th><th>IMPORTE</th></tr></thead><tbody>${v.items.map(p=>`<tr><td>${esc(p.name)}<small>${esc(p.code)} · ${money(Core.unitPrice(p.cents,v.channel||'Tienda'))}</small></td><td>${p.qty}</td><td>${money(p.qty*Core.unitPrice(p.cents,v.channel||'Tienda'))}</td></tr>`).join('')}</tbody></table></div>${v.delivery?pricingDetails(v.pricing):''}<div class="receipt-total"><span>Total</span><span>${money(v.total)}</span></div><p class="hint spacer">Recibido: ${money(v.received)} · Cambio: ${money(v.change)}<br>Catálogo: ${esc(v.source)}${v.priceDate?' · '+date(v.priceDate):''}</p>${v.posReference?'<div class="alert">Registrada en caja: '+esc(v.posReference.reference)+'<br>Responsable: '+esc(v.posReference.by)+' · '+date(v.posReference.at)+'</div>':''}${v.void?'<div class="alert error">Anulada: '+esc(v.void.reason)+'<br>Responsable: '+esc(v.void.by)+' · '+date(v.void.at)+'</div>':''}`,actions);}
function reconcile(id){modal('Confirmar registro en el sistema de caja',`<p class="hint">Primero ingresa esta venta en tu sistema habitual. Aquí se guarda la referencia para evitar duplicados. Esta acción no envía ventas a MSTG.</p><div class="form-stack"><div><label for="pos-ref">Número de factura / transacción del sistema</label><input id="pos-ref" maxlength="100"></div><div><label for="pos-by">Responsable</label><input id="pos-by" maxlength="80" value="${esc(db.profile.cashier)}"></div></div>`,[{label:'Volver',run:()=>saleDetail(id)},{label:'Guardar referencia',style:'primary',run:async()=>{const reference=$('pos-ref').value.trim(),by=$('pos-by').value.trim();if(!reference||!by)throw Error('Completa referencia y responsable.');await transaction(d=>{const v=d.sales.find(v=>v.id===id);if(!v||v.void||v.posReference)throw Error('El estado de la venta cambió.');if(d.sales.some(x=>x.store===v.store&&x.posReference?.reference===reference))throw Error('Esta referencia ya se usó en otra venta de la tienda.');v.posReference={reference,by,at:new Date().toISOString()};d.audit.push({action:'reconcile',id,...v.posReference});});saleDetail(id);}}]);}
function voidSale(id){modal('Anular comprobante',`<p class="hint">La venta permanecerá en el historial con su motivo. Anula solamente si el cobro no se realizó o si ya devolviste el dinero. Las ventas de jornadas cerradas se corrigen en el sistema habitual.</p><div class="form-stack"><div><label for="void-reason">Motivo de anulación</label><textarea id="void-reason" maxlength="300" rows="3"></textarea></div><div><label for="void-by">Responsable</label><input id="void-by" maxlength="80" value="${esc(db.profile.cashier)}"></div><label class="check-label"><input id="void-check" type="checkbox">Confirmo que no existe un cobro pendiente de devolución.</label></div>`,[{label:'Volver',run:()=>saleDetail(id)},{label:'Confirmar anulación',style:'danger',run:async()=>{const reason=$('void-reason').value.trim(),by=$('void-by').value.trim();if(!reason||!by||!$('void-check').checked)throw Error('Completa los datos y confirma la devolución.');await transaction(d=>{const v=d.sales.find(v=>v.id===id);if(!v||v.void||v.posReference)throw Error('La venta ya cambió de estado.');if(d.sessions.find(s=>s.id===v.sessionId)?.closed)throw Error('La jornada está cerrada. Registra el ajuste en el sistema habitual.');v.void={reason,by,at:new Date().toISOString()};d.audit.push({action:'void',id,...v.void});});saleDetail(id);}}]);}
function renderSetup(){const s=active(db),sales=s?db.sales.filter(v=>v.sessionId===s.id&&!v.void):[],cash=sales.filter(v=>v.method==='Efectivo').reduce((n,v)=>n+v.total,0),card=sales.filter(v=>v.method==='Tarjeta BAC').reduce((n,v)=>n+v.total,0),platform=sales.filter(v=>v.method==='Plataforma delivery').reduce((n,v)=>n+v.total,0);$('view-setup').innerHTML=heading('OPERACIÓN EN TIENDA','Tienda y caja','Una jornada identifica dónde, cuándo y quién registró cada venta.')+(s?`<div class="panel content-panel"><div class="section-title"><h2>${esc(s.store)} · Caja ${esc(s.till)}</h2><span class="badge">Jornada activa</span></div><p class="hint">${esc(s.cashier)} · ${esc(s.reason)}<br>Inicio: ${date(s.opened)}</p><div class="stats"><div class="stat"><span>Ventas en efectivo</span><strong>${money(cash)}</strong></div><div class="stat"><span>Tarjeta BAC</span><strong>${money(card)}</strong></div><div class="stat"><span>Plataformas delivery</span><strong>${money(platform)}</strong></div><div class="stat"><span>Efectivo esperado con fondo</span><strong>${money(s.opening+cash)}</strong></div></div><p class="hint">Fondo inicial: ${money(s.opening)} · ${sales.length} ventas válidas. No incluye retiros ni gastos: esta herramienta no registra movimientos de caja.</p><div class="actions spacer"><button id="close-session" class="button primary">Cerrar jornada</button><button id="setup-backup" class="button secondary">Crear respaldo</button></div></div>`:`<div class="panel content-panel"><h2>Inicia una jornada</h2><p class="hint">Selecciona una de las tiendas AMPM de El Salvador, identifica la caja y registra al responsable.</p><button id="start-session" class="button primary spacer">Preparar caja</button></div>`)+`<div class="panel content-panel"><h2>Impresora de la sucursal</h2><p class="hint">Ticket térmico de 80 mm. En delivery incluye espacio para firma del rider. Imprime una prueba antes de comenzar.</p><button id="printer-setup" class="button secondary">Configurar / probar impresión</button></div><div class="panel content-panel"><h2>Jornadas anteriores</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>TIENDA / CAJA</th><th>APERTURA</th><th>CIERRE</th><th>DIFERENCIA EFECTIVO</th></tr></thead><tbody>${[...db.sessions].reverse().map(s=>`<tr><td>${esc(s.store)} · ${esc(s.till)}<small>${esc(s.cashier)}</small></td><td>${date(s.opened)}</td><td>${s.closed?date(s.closed):'En curso'}</td><td>${s.closed?money(s.difference):'—'}${s.notes?'<small>'+esc(s.notes)+'</small>':''}</td></tr>`).join('')||'<tr><td colspan="4">Sin jornadas anteriores.</td></tr>'}</tbody></table></div></div>`;$('printer-setup').onclick=printerHelp;if(s){$('close-session').onclick=closeSession;$('setup-backup').onclick=backup;}else $('start-session').onclick=openSession;}
function closeSession(){const s=active(db);if(db.draft.items.length)return toast('Termina o vacía la venta en curso antes del cierre.');const expected=s.opening+db.sales.filter(v=>v.sessionId===s.id&&!v.void&&v.method==='Efectivo').reduce((n,v)=>n+v.total,0);modal('Cerrar jornada de emergencia',`<p class="hint">${esc(s.store)} · Caja ${esc(s.till)}. Las ventas pendientes se conservan para registrarlas después en el sistema.</p><div class="checkline"><span>Efectivo esperado, con fondo inicial</span><b>${money(expected)}</b></div><div class="form-stack"><div><label for="closing-cash">Efectivo contado (USD)</label><input id="closing-cash" inputmode="decimal" placeholder="0.00"></div><div><label for="closing-notes">Observaciones / explicación de diferencias</label><textarea id="closing-notes" rows="3" maxlength="500"></textarea></div></div>`,[{label:'Cancelar',run:closeModal},{label:'Cerrar y descargar respaldo',style:'primary',run:async()=>{const counted=Core.cents($('closing-cash').value),notes=$('closing-notes').value.trim();if(counted===null)throw Error('Ingresa el efectivo contado.');if(counted!==expected&&!notes)throw Error('Explica la diferencia de efectivo.');await transaction(d=>{if(d.active!==s.id||d.draft.items.length)throw Error('La jornada cambió. Revisa el cierre.');const fresh=s.opening+d.sales.filter(v=>v.sessionId===s.id&&!v.void&&v.method==='Efectivo').reduce((n,v)=>n+v.total,0);if(fresh!==expected)throw Error('Se registraron cambios en las ventas. Revisa el cierre.');Object.assign(active(d),{closed:new Date().toISOString(),expected,counted,difference:counted-expected,notes});d.active=null;d.draft=emptyDraft();});closeModal();await backup();toast('Jornada cerrada. Conserva el respaldo descargado.');}}]);}
function download(name,data,type){const u=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),15000);}
async function backup(){if(recoveryRaw){download('AMPM-recuperacion-datos-originales.json',recoveryRaw,'application/json');return;}const now=new Date().toISOString();if(!storageFailed)await transaction(d=>{d.lastBackup=now;},false);download((PRACTICE?'AMPM-PRACTICA-respaldo-':'AMPM-respaldo-')+now.replace(/[:.]/g,'-')+'.json',JSON.stringify({format:'ampm-emergency-backup',version:2,practice:PRACTICE,exportedAt:now,data:db},null,2),'application/json');if(view==='history')renderHistory();toast('Respaldo generado. Confirma que el archivo quedó en Descargas.');}
function exportSales(){
  const headers=['id','folio','fecha_UTC','tienda','caja','responsable','moneda','metodo','autorizacion','estado','factura_sistema','codigo','descripcion','cantidad','precio_unitario','importe_linea','total_venta','recibido','cambio','motivo_anulacion','jornada','canal','orden_delivery','rider','paquetes','observaciones_delivery','pricec_unitario','subtotal_pricec','incremento_delivery','base_sin_iva','iva_incluido','regla_precio'];const rows=[];
  for(const v of db.sales)for(const p of v.items){const channel=v.channel||'Tienda',unit=Core.unitPrice(p.cents,channel),q=v.pricing;rows.push([v.id,v.folio,v.created,v.store,v.till,v.cashier,'USD',v.method,v.reference,v.void?'ANULADA':v.posReference?'REGISTRADA':'PENDIENTE',v.posReference?.reference||'',p.code,p.name,p.qty,(unit/100).toFixed(2),(unit*p.qty/100).toFixed(2),(v.total/100).toFixed(2),(v.received/100).toFixed(2),(v.change/100).toFixed(2),v.void?.reason||'',v.sessionId,channel,v.delivery?.orderId||'',v.delivery?.rider||'',v.delivery?.packages||'',v.delivery?.notes||'',(p.cents/100).toFixed(2),((q?.baseTotal??v.total)/100).toFixed(2),((q?.surcharge||0)/100).toFixed(2),v.delivery?(q.net/100).toFixed(2):'',v.delivery?(q.vat/100).toFixed(2):'',q?.rule||'pricec-v1']);}
  download('AMPM-ventas-'+new Date().toISOString().slice(0,10)+'.csv',Core.exportCSV(headers,rows),'text/csv;charset=utf-8');toast('CSV generado. Cada fila es un producto; los totales e impuestos de venta se repiten por comprobante.');
}
function validBackup(b){if(b?.format!=='ampm-emergency-backup'||b.version!==2)throw Error('No es un respaldo AMPM v2.');if(Boolean(b.practice)!==PRACTICE)throw Error('Los respaldos de práctica y los registros reales se mantienen separados.');return Validate.validate(b.data);}
function restoreReview(d){modal('Restaurar respaldo',`<p class="hint">Contiene ${d.sales.length} ventas y ${d.catalog.products.length} productos.</p><div class="alert">La restauración reemplaza el registro local completo. Antes se descargará una copia del registro actual. Para evitar pérdida de ventas, solo se admite restaurar cuando todas las ventas locales están contenidas sin cambios en el respaldo.</div><label class="check-label"><input id="restore-check" type="checkbox">Verifiqué el archivo y quiero restaurar este registro.</label>`,[{label:'Cancelar',run:closeModal},{label:'Restaurar',style:'primary',run:async()=>{if(!$('restore-check').checked)throw Error('Confirma el archivo a restaurar.');if(db.draft.items.length)throw Error('Termina o vacía el carrito actual.');for(const v of db.sales){if(!d.sales.some(x=>x.id===v.id&&JSON.stringify(x)===JSON.stringify(v)))throw Error('El respaldo no contiene todas las ventas locales con su estado actual. Usa otro navegador para consultar este respaldo.');}await backup();await transaction(current=>{for(const v of current.sales)if(!d.sales.some(x=>x.id===v.id&&JSON.stringify(x)===JSON.stringify(v)))throw Error('El registro cambió durante la restauración.');const rev=current.revision,device=current.device,seq=Math.max(current.seq,d.seq);Object.assign(current,structuredClone(d));current.revision=rev;current.device=device;current.seq=seq;});closeModal();navigate('history');toast('Respaldo restaurado.');}}]);}
function renderHelp(){$('view-help').innerHTML=heading('GUÍA RÁPIDA','De la emergencia al cierre','Un flujo sencillo para el equipo de tienda.')+`<div class="grid-two"><div class="panel content-panel"><h2>Cómo trabajar</h2><div class="guide-list"><div class="guide-step"><div><b>Antes de la emergencia</b><p>Abre Iniciar AMPM.vbs y actualiza el catálogo desde MSTG. Revisa los precios y la tienda. Conserva esta carpeta y usa siempre el mismo navegador y dirección.</p></div></div><div class="guide-step"><div><b>Prepara la caja</b><p>Registra tienda, caja, responsable, motivo y fondo inicial. Asegura energía de respaldo para el equipo que utilizarás.</p></div></div><div class="guide-step"><div><b>Registra cada venta</b><p>Escanea, revisa cantidades y cobra. Confirma la venta e imprime el comprobante. El carrito se recupera al recargar.</p></div></div><div class="guide-step"><div><b>Cuando regrese el sistema</b><p>Exporta las ventas. Regístralas en la caja habitual y guarda aquí el número de factura. Cuenta el efectivo, cierra la jornada y conserva el respaldo.</p></div></div></div></div><div><div class="panel content-panel"><h2>Respuestas útiles</h2><p class="hint"><b>¿Funciona sin Internet?</b><br>Sí. Catálogo, búsqueda, cobro, historial e impresión funcionan localmente. La actualización MSTG requiere conexión.<br><br><b>¿Emite la factura del sistema habitual?</b><br>Emite un comprobante de contingencia. La emisión fiscal y el registro definitivo deben completarse en el sistema autorizado.<br><br><b>¿Las ventas se envían a MSTG?</b><br>No. La conexión consulta los precios. El traslado de ventas se controla con CSV y referencias del sistema de caja.<br><br><b>¿Se comparten los registros entre cajas?</b><br>No. Cada navegador conserva su propio registro. Los folios incluyen identificador del equipo. No uses modo incógnito ni borres los datos del navegador antes de respaldar.<br><br><b>¿Qué ocurre con precios cero?</b><br>El producto aparece en el catálogo, pero no puede cobrarse. Corrige su precio en origen y actualiza.<br><br><b>¿Qué impuestos se agregan?</b><br>En tienda se cobra PriceC. En PedidosYa y Uber Eats se incrementa 10% por unidad, redondeado a centavos. PriceC ya incluye IVA: el total delivery también lo incluye. Se desglosa el 13% sin sumarlo de nuevo. Ejemplo: $10.00 → $11.00.<br><br><b>¿Cómo entrego una orden delivery?</b><br>Selecciona la plataforma, ingresa su número de orden. Registra el medio de pago correcto. Imprime el ticket de 80 mm, pide nombre, firma y hora al rider, y conserva la copia. Puedes reimprimir desde el historial sin crear otra venta.<br><br><b>¿Cómo preparo la impresora?</b><br>En Tienda y caja usa Configurar / probar impresión. Selecciona la impresora instalada, papel 80 mm, escala 100% y desactiva encabezados y pies. La firma se recoge en papel; imprimir no confirma por sí solo la entrega.</p></div><div class="panel content-panel"><h2>Datos y recuperación</h2><p class="hint"><a class="link" href="?practica=1" target="_blank" rel="noopener">Abrir modo práctica</a> · Usa este espacio para capacitarte sin mezclar ventas reales.</p><p class="hint">Un respaldo JSON contiene catálogo, jornadas, ventas y carrito. Un CSV es un reporte para conciliación; no restaura la aplicación. Cada línea del CSV es un producto y el total de la venta se repite.</p><button id="help-backup" class="button secondary spacer">Crear respaldo ahora</button>${localStorage.getItem('ventas_emergencia')?'<button id="legacy-backup" class="button secondary spacer">Descargar registro del HTML anterior</button>':''}</div></div></div>`;$('help-backup').onclick=backup;if($('legacy-backup'))$('legacy-backup').onclick=()=>download('ventas-version-anterior.json',localStorage.getItem('ventas_emergencia'),'application/json');}
document.addEventListener('click',async e=>{try{const nav=e.target.closest('[data-view]');if(nav)navigate(nav.dataset.view);const product=e.target.closest('[data-product]');if(product)await add(product.dataset.product);const qty=e.target.closest('[data-qty]');if(qty){const code=db.draft.items[Number(qty.dataset.qty)]?.code;await transaction(d=>{const p=d.draft.items.find(p=>p.code===code);if(!p)return;const n=p.qty+Number(qty.dataset.delta);if(n<1||n>9999)return;p.qty=n;});}const remove=e.target.closest('[data-remove]');if(remove){const code=db.draft.items[Number(remove.dataset.remove)]?.code;await transaction(d=>{d.draft.items=d.draft.items.filter(p=>p.code!==code);});}const sale=e.target.closest('[data-sale]');if(sale)saleDetail(sale.dataset.sale);if(e.target.closest('#last-print'))saleDetail(lastSaleId);}catch{}});
$('search').oninput=search;$('search-form').onsubmit=async e=>{e.preventDefault();const q=$('search').value.trim(),exact=db.catalog.products.find(p=>p.code.toLowerCase()===q.toLowerCase());if(exact){try{await add(exact.code);}catch{}}else{search();toast('Selecciona el producto en los resultados o escanea el código completo.');}};
for(const id of ['method','received','reference'])$(id).addEventListener('input',()=>{paymentView();const value=$(id).value;transaction(d=>{d.draft[id]=value;},false).catch(()=>{});});
$('exact').onclick=()=>{const value=(Core.quote(db.draft.items,db.draft.channel).total/100).toFixed(2);$('received').value=value;paymentView();transaction(d=>{d.draft.received=value;},false).catch(()=>{});};
$('clear-cart').onclick=()=>modal('Vaciar venta en curso','<p class="hint">Se quitarán los productos de este carrito. Las ventas registradas se conservan.</p>',[{label:'Volver',run:closeModal},{label:'Vaciar carrito',style:'danger',run:async()=>{await transaction(d=>{d.draft=emptyDraft();});closeModal();}}]);
$('channel').onchange=async()=>{const channel=$('channel').value;try{await transaction(d=>{d.draft.channel=channel;d.draft.received='';d.draft.reference='';d.draft.method=Core.isDelivery(channel)?'Plataforma delivery':'Efectivo';});search();}catch{}};
for(const [id,key] of [['order-id','orderId'],['rider-name','rider'],['delivery-notes','notes']])$(id).oninput=()=>{const value=$(id).value;transaction(d=>{d.draft.delivery[key]=value;},false).catch(()=>{});};
$('delivery-print-help').onclick=printerHelp;
$('checkout').onclick=reviewCheckout;$('session-button').onclick=openSession;$('source-open').onclick=()=>navigate('catalog');$('help-top').onclick=()=>navigate('help');$('close-modal').onclick=closeModal;
$('import-file').onchange=async e=>{const f=e.target.files[0];try{if(!f)return;if(f.size>10_000_000)throw Error('Archivo demasiado grande. Máximo 10 MB.');const sheets=/\.xlsx$/i.test(f.name)?await readXlsx(f):/\.csv$/i.test(f.name)?[{name:f.name,rows:Core.csv(await f.text())}]:(()=>{throw Error('Usa un archivo .xlsx o .csv.');})();prepareImport(sheets,{source:'Archivo · '+f.name,syncedAt:null,importedAt:new Date().toISOString(),reportId:null});}catch(e){toast(e.message);}finally{e.target.value='';}};
$('restore-file').onchange=async e=>{const f=e.target.files[0];try{if(!f)return;if(f.size>30_000_000)throw Error('El respaldo supera 30 MB.');restoreReview(validBackup(JSON.parse(await f.text())));}catch(e){toast('No se restauró el archivo. '+e.message);}finally{e.target.value='';}};
document.addEventListener('keydown',e=>{if(e.key==='F2'){e.preventDefault();if(!$('modal').open){navigate('sale');$('search').focus();$('search').select();}}if(e.key==='F8'){e.preventDefault();if(!$('modal').open&&view==='sale')reviewCheckout();}});
window.addEventListener('storage',e=>{if(e.key===KEY){try{db=load();render();toast('Registro actualizado desde otra pestaña de este equipo.');}catch(err){storageError(err);}}});window.addEventListener('online',render);window.addEventListener('offline',render);render();
